chrome.runtime.onInstalled.addListener(()=>{chrome.contextMenus.removeAll(()=>{chrome.contextMenus.create({id:`always-pdf-tools`,title:`AlwaysPDF Tools로 열기`,contexts:[`link`],documentUrlPatterns:[`<all_urls>`]})})}),chrome.contextMenus.onClicked.addListener(e=>{if(e.menuItemId===`always-pdf-tools`&&e.linkUrl){let e=chrome.runtime.getURL(`src/pages/index.html`);chrome.tabs.create({url:e})}});